// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface INCOME {
    function owner() external view returns (address);
    function closeTrade() external;
    function isOpen() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x3a91A88Ef4bB813BB99EF5a745bcb56e3A3b403b;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner
        address currentOwner = INCOME(TARGET).owner();

        // Impersonate the owner and call closeTrade()
        vm.prank(currentOwner);
        INCOME(TARGET).closeTrade();

        // Verify the exploit worked - isOpen should be false
        bool isOpenAfter = INCOME(TARGET).isOpen();
        assertEq(isOpenAfter, false, "isOpen should be false after closeTrade()");
        assertEq(isOpenAfter, false, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
